/// <summary>
/// Data contract class for the cover note report
/// </summary>
[DataContract]
class METSalesOrderShipmentBundlingReportContract
{
    boolean         isFirstReport;
    MetShipmentId   shipmentId;
    MetLoadId       loadId;

}

Method.Source:
/// <summary>
/// Parm method for the load number
/// </summary>
/// <param name = "loadId">the load number</param>
/// <returns>the load number</returns>
[DataMemberAttribute('loadId')]
public MetLoadId parmLoadId(MetLoadId _loadId = loadId)
{
    loadId = _loadId;
    return loadId;
}

/// <summary>
/// Parm method for the shipment number
/// </summary>
/// <param name = "_shipmentId">the shipment number</param>
/// <returns>the shipment number</returns>
[DataMemberAttribute('shipmentId'),
    SysOperationControlVisibilityAttribute(false)]
public MetShipmentId parmShipmentId(MetShipmentId _shipmentId = shipmentId)
{
    shipmentId = _shipmentId;
    return shipmentId;
}

/// <summary>
/// Parm method for the shipment number
/// </summary>
/// <param name = "_isFirstReport">the shipment number</param>
/// <returns>the shipment number</returns>
[DataMemberAttribute('IsFirstReport'),
    SysOperationControlVisibilityAttribute(false)]
public boolean parmIsFirstReport(boolean _isFirstReport = isFirstReport)
{
    isFirstReport = _isFirstReport;
    return isFirstReport;
}
